function prng(seed){var a=(seed>>>0)||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
function demoRun(seed){var R=prng(seed*15485863+11);var input=[],T=200,n=8;for(var i=0;i<n;i++)input.push(+(R()*2-1).toFixed(3));var spikes=0,sum2=0;var decoded=input.map(function(v){var rate=(v+1)/2,s=0;for(var t=0;t<T;t++){if(R()<rate){s++;spikes++;}}var est=s/T*2-1;sum2+=(est-v)*(est-v);return+est.toFixed(3);});return{neurons:n,steps:T,mse:+(sum2/n).toFixed(4),total_spikes:spikes,sparsity_pct:+(100*(1-spikes/(n*T))).toFixed(1)};}
var SEED = 79501;
console.log(JSON.stringify(demoRun(SEED), null, 1));

